            if (isempty(g_cocs_multi_sa_printErrorMsg) || (g_cocs_multi_sa_printErrorMsg == 1))
               fprintf('ERROR: Attribute list no yet defined for parameter %s\n', a_paramName);
            end

            again = 0;
         end
   end
   if (~isempty(o_attributeStruct))
      if ((again == 2) || (again == 3))
         o_attributeStruct.name = a_paramName;
      end
      again = 0;
   end
end

return

% ------------------------------------------------------------------------------
% Associate an institution name to a given data centre information.
%
% SYNTAX :
%  [o_institution] = get_institution_from_data_centre(a_dataCentre, a_printWarningFlag)
%
% INPUT PARAMETERS :
%   a_dataCentre       : data centre
%   a_printWarningFlag : print a warning if input data centre is unknown
%
% OUTPUT PARAMETERS :
%   o_institution : institution
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   12/01/2014 - RNU - creation
% ------------------------------------------------------------------------------
function [o_institution] = get_institution_from_data_centre(a_dataCentre, a_printWarningFlag)

o_institution = '';

% current float WMO number
global g_decArgo_floatNum;


switch (a_dataCentre)

   case 'AO'
      o_institution = 'AOML';
   case 'BO'
      o_institution = 'BODC';
   case 'CI'
      o_institution = 'Institute of Ocean Sciences';
   case 'CS'
      o_institution = 'CSIRO';
   case 'GE'
      o_institution = 'BSH';
   case 'GT'
      o_institution = 'GTS';
   case 'HZ'
      o_institution = 'CSIO';
   case 'IF'
      o_institution = 'CORIOLIS';
   case 'IN'
      o_institution = 'INCOIS';
   case 'JA'
      o_institution = 'JMA';
   case 'JM'
      o_institution = 'JAMSTEC';
   case 'KM'
      o_institution = 'KMA';
   case 'KO'
      o_institution = 'KIOST';
   case 'MB'
      o_institution = 'MBARI';
   case 'ME'
      o_institution = 'MEDS';
   case 'NA'
      o_institution = 'NAVO';
   case 'NM'
      o_institution = 'NMDIS';
   case 'PM'
      o_institution = 'PMEL';
   case 'RU'
      o_institution = 'RUSSIA';
   case 'SI'
      o_institution = 'SIO';
   case 'SP'
      o_institution = 'SPAIN';
   case 'UW'
      o_institution = 'University of Washington';
   case 'VL'
      o_institution = 'Far Eastern Regional Hydrometeorological Research Institute of Vladivostock';
   case 'WH'
      o_institution = 'Woods Hole Oceanographic Institution';

   otherwise
      if (a_printWarningFlag)
         fprintf('WARNING: Float #%d: No institution assigned to data centre %s\n', ...
            g_decArgo_floatNum, ...
            a_dataCentre);
      end
end

return

% ------------------------------------------------------------------------------
% Compute the profile quality flag of a given parameter.
%
% SYNTAX :
%  [o_profQc] = compute_profile_quality_flag(a_qcFlags)
%
% INPUT PARAMETERS :
%   a_qcFlags : QC flags of the parameter
%
% OUTPUT PARAMETERS :
%   o_profQc : computed profile quality flag
%
% EXAMPLES :
%
% SEE ALSO : 
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   04/09/2014 - RNU - creation
% ------------------------------------------------------------------------------
function [o_profQc] = compute_profile_quality_flag(a_qcFlags)

% QC flag values
global g_decArgo_qcStrDef;           % ' '
global g_decArgo_qcStrNoQc;          % '0'
global g_decArgo_qcStrGood;          % '1'
global g_decArgo_qcStrProbablyGood;  % '2'
global g_decArgo_qcStrCorrectable;   % '3'
global g_decArgo_qcStrBad;           % '4'
global g_decArgo_qcStrChanged;       % '5'
global g_decArgo_qcStrInterpolated;  % '8'
global g_decArgo_qcStrMissing;       % '9'

% output parameters initialization
o_profQc = g_decArgo_qcStrDef;

if (length(find((a_qcFlags == g_decArgo_qcStrDef) | ...
      (a_qcFlags == g_decArgo_qcStrNoQc) | ...
      (a_qcFlags == g_decArgo_qcStrMissing))) ~= length(a_qcFlags))

   % compute the ratio of good data
   nbUsefulLev = length(find((a_qcFlags ~= g_decArgo_qcStrDef) & ...
      (a_qcFlags ~= g_decArgo_qcStrNoQc) & ...
      (a_qcFlags ~= g_decArgo_qcStrMissing)));
   nbGoodLev = length(find((a_qcFlags == g_decArgo_qcStrGood) | ...
      (a_qcFlags == g_decArgo_qcStrProbablyGood) | ...
      (a_qcFlags == g_decArgo_qcStrChanged) | ...
      (a_qcFlags == g_decArgo_qcStrInterpolated)));
   ratio = 100*nbGoodLev/nbUsefulLev;
   if (ratio == 0)
      o_profQc = 'F';
   elseif (ratio < 25)
      o_profQc = 'E';
   elseif (ratio < 50)
      o_profQc = 'D';
   elseif (ratio < 75)
      o_profQc = 'C';
   elseif (ratio < 100)
      o_profQc = 'B';
   else
      o_profQc = 'A';
   end
end

return
